# -*- coding: utf-8 -*-
# Обновление системного промта kip8test до post-Task 315
# (бар из ТРЁХ РАВНЫХ частей с окном мероприятий месяца; перенос
#  текста в окнах; кнопка «Отменить» + строки 2/3 тулбара)
with open('Системный_промт_для_приложения_КИПиА.md', encoding='utf-8') as f:
    lines = f.readlines()

new3 = '''> **Версия документа:** 2026-09-04 (post-Task 315: БАР НАД ШАХМАТКОЙ — ТРИ РАВНЫЕ ЧАСТИ (кнопки | окно ВСЕХ мероприятий месяца | окно времени и праздников), ТЕКСТ В ОКНАХ ПЕРЕНОСИТСЯ; КНОПКА «ОТМЕНИТЬ» РЯДОМ С «СОХРАНИТЬ» (СТРОКА 2), «СФОРМИРОВАТЬ» — СТРОКОЙ 3. Заявка пользователя: «В баре над шахматкой добавь второе окно с данными всех мероприятий на открытый месяц, расположи это окно между кнопками и окном времени и праздников, раздели бар на три равных части, для кнопок и двух окон. Если текст в окнах не будет помещаться в одну строку, он должен переноситься на строку ниже. При добавлении нового кода или мероприятия в ячейки шахматки, помимо кнопки "Сохранить" должна появляться кнопка "Отменить", для отмены ввода изменений. Кнопки "Сохранить" и "Отменить" расположи под кнопками выбора месяца и года, кнопку "Сформировать" ещё ниже, в третьей строке». СОДЕРЖАНИЕ: 1) БАР: .ws-toolbar — три строки: СТРОКА 1 .ws-bar-row — десктоп ≥1024px grid 1fr 1fr 1fr (ТРИ РАВНЫЕ части: .ws-toolbar-main [селекты + «Обновить» + штамп] | #wsEventsPanel [НОВОЕ окно мероприятий месяца] | #wsCalPanel [окно времени и праздников]; mobile <1024px — колонка: кнопки сверху, окна под ними, окно мероприятий во всю ширину); прежняя компоновка Task 269/272 (кнопки слева / окошко справа fit-content, order/align-self/margin-right: auto/nowrap) УДАЛЕНА, margin-left: auto у «Сформировать» удалён. СТРОКА 2 .ws-actions-row (#wsActionsRow) — «Сохранить» + «Отменить» (появляются при вводе изменений, скрыты без правок — пустая строка не занимает места); СТРОКА 3 .ws-generate-row (#wsGenerateRow) — «Сформировать» (вид — по праву записи в init, синхронно с кнопкой). 2) ОКНО МЕРОПРИЯТИЙ #wsEventsPanel (.ws-events-panel, 95px, скролл внутри, overscroll contain, стиль един с календарём, светлая #e9e7de): заголовок-плашка «Мероприятия · {месяц} {год} · {N}» (зелёная) + строки «точка-цвет (из «Коды_статусов», как у бейджей) · диапазон дат («02.09»/«02–05.09»/«29.09–02.10») · код · тема · ФИО»; попадают записи листа «Инструктажи» (_TRAININGS), ПЕРЕСЕКАЮЩИЕ месяц (ISO-сравнение диапазонов, как _eventsAt); сортировка по дате начала + таб. номеру; пустой месяц — «нет мероприятий в этом месяце»; заполняет _renderMonthEventsPanel (вызов из _renderGrid — смена месяца/загрузка/«Обновить»/мутации). 3) ПЕРЕНОС ТЕКСТА (заявка): .ws-ep-item — white-space: normal + overflow-wrap: break-word (дата nowrap — «02–05.09» не рвётся); .ws-cp-day (чипы праздников) и .ws-cp-item (счётчики норм) — тоже normal; горизонтального переполнения нет (проверено численно), большой объём — вертикальный скролл внутри окон. 4) «ОТМЕНИТЬ» (отмена ввода изменений): #wsCancelBtn (.ws-cancel-btn, приглушённо-красная, 34px) в строке 2, появляется ВМЕСТЕ с «Сохранить» (права + _PENDING не пуст) — _updateSaveBtn управляет обеими кнопками и всей строкой 2; cancelAll(): kipConfirm (danger, «Отменить правки») → _PENDING = {} → _updateSaveBtn + _renderGrid (ячейки возвращаются к серверным данным) → тост «Изменения отменены (N)»; блокируется при _saving; мероприятия копятся НЕ локально (шторка отправляет сразу) — отменять нечего, до подтверждения действует «Отмена» шторки. Сервер/листы/Apps Script НЕ менялись. Тесты: 1584 → 1609/0 (+25 test-task315.js; актуализированы test-work-schedule/test-prod-calendar + browser-check 306/307/308; SW-бамп v553→v554 в 15 тест-файлах). Верификация: task315-browser-check.py 33/33 (3 контекста, порт 8937: grid 3 равные части — разброс ширин ≤ 8px; окно: заголовок/счётчик/строки/фильтр месяца/диапазоны/цвет точки; перенос численно — длинная тема 5 строк, переполнений нет; строка 2 при правке «Сохранить (1)»+«Отменить» ниже окон, строка 3 ниже строки 2; «Отменить» → kipConfirm → сброс/тост/возврат ячейки; «Сохранить» → setManualEntry; светлая; зритель: строки 2/3 скрыты, окно живо; мобильный 375px: бар колонкой, окно во всю ширину); регресс 298 34/34, 303 20/20, 304 10/10, 305 20/20, 306 29/29, 307 20/20, 308 20/20, 309 26/26, 310 20/20, 311 24/24, 312 31/31, 313 30/30, 314 36/36; VLM ×4 (desktop-замечание опровергнуто численными измерениями). ПЕРЕНОС В kip8: НЕ выполнен — Task 315 ожидает проверки пользователем в kip8test (после проверки — одним коммитом, kip8 v417→v418). Деплой пользователя: GitHub Pages + Ctrl+Shift+R ×1–2; Apps Script НЕ трогать.)
'''

assert lines[2].startswith('> **Версия документа:**')
lines.insert(2, new3 if new3.endswith('\n') else new3 + '\n')
prev = [i for i, l in enumerate(lines[:40]) if l.startswith('> **Версия документа (предыдущая):**')]
while len(prev) > 12:
    del lines[prev[-1]]
    prev = [i for i, l in enumerate(lines[:40]) if l.startswith('> **Версия документа (предыдущая):**')]
print('Строка 3 вставлена; цепочка «предыдущих»:', len(prev))

src = ''.join(lines)

reps = [
    ('> **Текущая версия кэша:** `kipia-test-v553`',
     '> **Текущая версия кэша:** `kipia-test-v554`'),
    ('| `kip8test` | PWA | `kipia-test-v553` |',
     '| `kip8test` | PWA | `kipia-test-v554` |'),
]
for old, new in reps:
    n = src.count(old)
    assert n == 1, (old, n)
    src = src.replace(old, new)
print('Версии кэша обновлены (2 замены)')

# Счётчики тестов
reps2 = [
    ('├── tests/                      # 1584 юнит-тестов (Node.js, 32 файлов)',
     '├── tests/                      # 1609 юнит-тестов (Node.js, 33 файлов)'),
    ('ожидается `1584 passed, 0 failed`', 'ожидается `1609 passed, 0 failed`'),
    ('# Ожидается: 1584 passed, 0 failed', '# Ожидается: 1609 passed, 0 failed'),
]
for old, new in reps2:
    n = src.count(old)
    assert n == 1, (old, n)
    src = src.replace(old, new)
print('Счётчики тестов обновлены (3 замены)')

# Буллет Task 315 — после буллета Task 314 (новые задачи ниже)
entry = ('\n- **График работы — бар из ТРЁХ РАВНЫХ частей с окном ВСЕХ мероприятий месяца, перенос текста в окнах, кнопка «Отменить», строки 2/3 тулбара (Task 315)**: '
         'по заявке пользователя: 1) БАР: .ws-toolbar — три строки. СТРОКА 1 .ws-bar-row: десктоп ≥1024px — grid-template-columns: 1fr 1fr 1fr (ТРИ РАВНЫЕ ЧАСТИ): .ws-toolbar-main [селекты месяца/года + «Обновить» (Task 314) + штамп «данные от …»] | #wsEventsPanel [НОВОЕ окно мероприятий месяца] | #wsCalPanel [окно времени и праздников Task 264/266/270]; mobile <1024px — колонка (кнопки сверху, окна под ними), окно мероприятий — во всю ширину; прежняя компоновка Task 269/272 (кнопки слева / окошко справа на fit-content; order/align-self/margin-right: auto/nowrap) УДАЛЕНА; margin-left: auto у «Сформировать» удалён (своя строка); СТРОКА 2 .ws-actions-row #wsActionsRow — «Сохранить» (#wsSaveBtn, Task 251) + «Отменить» (#wsCancelBtn, НОВАЯ), появляются при вводе изменений (пустая строка скрыта display:none по [hidden] — не занимает места); СТРОКА 3 .ws-generate-row #wsGenerateRow — «Сформировать» (вид по праву записи в init синхронно с кнопкой; подтверждение и тихое обновление календаря — прежние). '
         '2) ОКНО МЕРОПРИЯТИЙ #wsEventsPanel (.ws-events-panel): стиль един с окошком календаря (bg-tertiary, прямые углы, height 95px, overflow-y auto, overscroll-behavior contain; светлая #e9e7de, рамка rgba(0,0,0,0.12)); заголовок-плашка «Мероприятия · {месяц} {год} · {N}» (.ws-ep-cap, зелёная, перенос); строки .ws-ep-item «точка-цвет .ws-ep-dot (цвет кода из «Коды_статусов» — как у бейджей ячеек) · диапазон дат .ws-ep-date («02.09» / «02–05.09» / «29.09–02.10» — nowrap, не рвётся) · .ws-ep-text (код · тема · ФИО)», тултип с полным описанием; попадают записи листа «Инструктажи» (_TRAININGS), ПЕРЕСЕКАЮЩИЕ открытый месяц (дата_начала..дата_окончания, ISO-сравнение лексикографически = хронологически, как _eventsAt — мероприятие 29.08–02.09 видно в обоих месяцах); сортировка по дате начала, затем таб. номеру; пустой месяц — «нет мероприятий в этом месяце»; _renderMonthEventsPanel вызывается из _renderGrid (смена месяца, загрузка с сети/кэша, «Обновить», мутации мероприятий). '
         '3) ПЕРЕНОС ТЕКСТА В ОКНАХ (заявка «если текст не помещается в одну строку — переносится на строку ниже»): .ws-ep-item — white-space: normal + overflow-wrap: break-word; .ws-cp-day (чипы праздников «1 янв · Новогодние каникулы») и .ws-cp-item (счётчики норм) — тоже normal (было nowrap); горизонтального переполнения окон нет (проверено численно: itemOverflow/textOverflow false), большой объём — вертикальный скролл внутри (95px). '
         '4) КНОПКА «ОТМЕНИТЬ» (отмена ввода изменений): #wsCancelBtn (.ws-cancel-btn — приглушённо-красная rgba(255,107,107,0.14)/#ff8a8a, светлая #b02c2c; 34px в ряду, прямые углы) — в строке 2 рядом с «Сохранить»; появляется ВМЕСТЕ с ней: _updateSaveBtn — show = _canEdit && n > 0, управляет кнопками И всей строкой 2 (wsActionsRow.hidden); cancelAll(): guard _saving → kipConfirm (danger-кнопка «Отменить правки», текст «Отменить ввод изменений — все несохранённые правки шахматки (N)?») → doRevert: _PENDING = {} + _updateSaveBtn + _renderGrid (ячейки возвращаются к СЕРВЕРНЫМ данным) + тост «Изменения отменены (N)»; без правок/подтверждения «Отмена» — ничего не делает; мероприятия копятся НЕ локально (шторка «+ Мероприятие…» отправляет на сервер сразу при подтверждении) — несохранённого ввода мероприятий не бывает, отмена до подтверждения — кнопка «Отмена» шторки; «Сохранить» (saveAll) — прежний пакетный путь без изменений. '
         'Сервер WorkSchedule.gs/листы/Apps Script/кэш kip8_ws_cache_v1/«Обновить»/бейджи/попапы/карточка — НЕ менялись. Верификация: сьют 1584→1609/0 (+25 tests/test-task315.js: HTML [бар/строки/порядок], CSS [grid 1fr 1fr 1fr, перенос, «Отменить»], JS-скелет, VM [_renderMonthEventsPanel: фильтр/форматы/пусто; _updateSaveBtn: n=0/n=2/зритель; cancelAll: сброс/тост], SW v554; актуализированы test-work-schedule [десктоп — 3 равные части; _updateSaveBtn], test-prod-calendar [media — grid], browser-check 306 [кнопки по строкам]/307/308 [wrap]; SW-бамп v553→v554 в 15 тест-файлах), task315-browser-check.py 33/33 (порт 8937, 3 контекста: десктоп-Админ [grid, разброс ширин трёх частей ≤ 8px; окно: заголовок «Мероприятия · {м} {г} · 4», записи след. месяца НЕ показаны, диапазоны «10.MM»/«12–15.MM»/пересечение границы, цвет точки #B3E5FC, перенос whiteSpace normal, длинная тема многострочная; без правок строка 2 скрыта, строка 3 видна; правка → «Сохранить (1)»+«Отменить», строка 2 ниже окон бара, строка 3 ниже строки 2; «Отменить» → kipConfirm danger → _PENDING пуст/строка скрыта/тост/ячейка вернулась к «Д»; «Сохранить» → setManualEntry/тост; светлая #e9e7de; 0 JS-ошибок], зритель «ИТР8 pro» [строки 2/3 скрыты, окно мероприятий работает], мобильный 375px [бар колонкой, окно во всю ширину бара, «Сформировать» ниже]); численная проверка переполнения: длинная тема 5 строк (81px), переполнений нет, вертикальный скролл есть; регресс 298 34/34, 303 20/20, 304 10/10, 305 20/20, 306 29/29, 307 20/20, 308 20/20, 309 26/26, 310 20/20, 311 24/24, 312 31/31, 313 30/30, 314 36/36; VLM ×4 (desktop/actions/light/mobile; замечание VLM по desktop — «неравные части/обрезка» — опровергнуто численными измерениями: колонки равны до 8px, переполнений нет). SW kipia-test-v553→v554. ДЕПЛОЙ: только фронтенд — GitHub Pages + Ctrl+Shift+R ×1–2; Apps Script НЕ трогать — см. scripts/DEPLOY-Task315-bar-events-cancel.md')
lines2 = src.split('\n')
insert_at = None
for i, l in enumerate(lines2):
    if l.startswith('- **График работы — «.» → «·» + фон пустой ячейки'):
        j = i + 1
        while j < len(lines2) and lines2[j].startswith('  '):
            j += 1
        insert_at = j
        break
assert insert_at is not None, 'точка вставки (после буллета Task 314) не найдена'
lines2.insert(insert_at, entry)
src = '\n'.join(lines2)
print('Буллет Task 315 вставлен (после Task 314)')

with open('Системный_промт_для_приложения_КИПиА.md', 'w', encoding='utf-8') as f:
    f.write(src)
print('Промт обновлён: post-Task 315, кэш v554, тесты 1609/33')
